// === belanja.js ===
export function total(item) {
  return item.reduce((t, x) => t + x, 0);
}
// === ongkir.js ===
export function total(km) {
  return km * 2000;
}
// === main.js ===
import { total as totalBelanja } from "./belanja.js";
import { total as totalOngkir } from "./ongkir.js";
console.log(totalBelanja([18000, 15000]));
console.log(totalOngkir(5));
